D.DynamicSpellTexts[143497]={Description={Key="0be977f644936111:331",Text="鲁克·石趾、禾·软足和孙·柔心共享一个灵魂链接，该链接将他们的命运紧密联系在一起。当生命值降到1点时，只要其他守护者还在继续战斗，他们就将开始施放金莲的羁绊，并在完成时恢复{2}%的最大生命值。\r\n\r\n将全部三名守护者的生命值同时降至1点才能令他们的头脑清醒过来。",Count=3,Constants={[1]=1,[3]=1},Equals={}},Aura={Key="1386311756baa48e:19",Text="恢复{1}%的生命值。",Count=1,Constants={},Equals={}}}
