D.DynamicSpellTexts[158563]={Description={Key="62b4e566b7cf77b7:110",Text="高里亚劫掠者一脚踢在玩家脸上，造成{1}点物理伤害，清除所有威胁值并将其击退。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[158602]={Description={Key="96da26c08b53866f:156",Text="加安上将部署一门可旋转式支配者炮台，持续进行支配者轰击直至被摧毁。\r\n\r\n支配者轰击会对命中的任意玩家造成{1}点火焰伤害。",Count=1,Constants={},Equals={}}}
