D.DynamicSpellTexts[182169]={Description={Key="60d60743ac3bc1cc:86",Text="每当有一个灵魂被腐蚀并驱逐，就会使血魔受到的伤害降低{1}%。",Count=1,Constants={},Equals={}},Aura={Key="46306957907df22a:27",Text="受到的伤害降低{1}%。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[182173]={Description={Key="bcc13d00c5abca9f:303",Text="暗影领主艾斯卡掷出邪能飞轮，在三名玩家之间来回弹射后回到其手中。邪能飞轮触碰到这些目标时会发生爆炸，对所有敌人最多造成{1}点火焰伤害，伤害高低取决于其距离爆炸点的距离。此外飞轮命中目标前，还会对其路径上的任意玩家造成{2}点火焰伤害。",Count=2,Constants={},Equals={}}}
D.DynamicSpellTexts[182225]={Description={Key="9caddefc7ff661e9:164",Text="阿克蒙德召唤一阵流星雨企图毁灭德拉诺，每次冲击对所有玩家造成{1}点火焰伤害。离冲击点越远的玩家受到的伤害越低。",Count=1,Constants={},Equals={}}}
